    /// <summary>The tick as floats in [-1, 1] (decoded once, cached).</summary>
    public static float[] Get()
    {
        if (_cache != null) return _cache;
        var bytes = System.Convert.FromBase64String(Base64Pcm16);
        var f = new float[bytes.Length / 2];
        for (int i = 0; i < f.Length; i++) f[i] = (short)(bytes[2 * i] | (bytes[2 * i + 1] << 8)) / 32768f;
        return _cache = f;
    }
